-- TBCBisTracker Database
-- Best-in-Slot gear for all classes and specs across all TBC phases.
-- Item IDs match Wowhead TBC Classic (https://www.wowhead.com/tbc/item=<id>).
-- Source types: "crafted","heroic","raid","reputation","pvp","world","quest","dungeon"
--
-- STATUS: prebis + phase1 populated for all class/spec combinations.
--   Phases 2–5 still empty placeholders.
--
-- Data source: wowhead TBC Classic BiS guides (server-rendered HTML extraction).
--   prebis: /tbc/guide/classes/<class>/<spec>/<role>-bis-gear-pve-pre-raid (or
--           class/role for shared guides — rogues, mages, warlocks)
--   phase1: /tbc/guide/<slug>-karazhan-best-in-slot-gear-burning-crusade-classic-wow
-- Some specs share their class's guide (rogues, mages, warlocks share one DPS guide;
-- priest disciple shares with holy via DB alias).

TBCBisTracker = TBCBisTracker or {}
TBCBisTracker.DB = {}

local DB = TBCBisTracker.DB

local function item(id, source, sourceType, note)
    return { id = id, source = source, sourceType = sourceType or "raid", note = note }
end

local function EMPTY_PHASES()
    return { prebis = {}, phase1 = {}, phase2 = {}, phase3 = {}, phase4 = {}, phase5 = {}, pvp = {} }
end

